// Get color for a service name (deterministic fallback for unknown services)
export function serviceColor(name) {
  if (!name) return '#606570';
  const upper = name.toUpperCase();
  for (const [key, color] of Object.entries(SERVICE_COLORS)) {
    if (upper.includes(key.toUpperCase())) return color;
  }
  // Deterministic color from name
  let h = 0;
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) & 0xffffff;
  return `hsl(${h % 360}, 50%, 55%)`;
}

